"""Team banners and flags for DrakesServerTeams, modelled in Blender (nothing here is generated by the mod at runtime).

Run headless:   blender -b --factory-startup -P make_team_banners.py -- <out_dir> [preview]
Run in a live Blender (MCP):  set sys.argv = ["x", "--", out_dir, "preview"] then exec the file.

Writes four .glb files (and team_banners.blend):
  banner_hanging   wall banner on a crossbar with wall brackets (origin: bar centre, wall plane at y = 0)
  banner_standing  free-standing banner pole with a foot (origin: centre of the foot, on the ground)
  flag_standard    free-standing flag pole with a side flag and a round foot (origin: centre of the foot)
  banner_carry     light carried banner pole with a spiked butt (origin: the butt; grip is at z = 0.9..1.3)

Axes: Blender X = width, Y = depth (FRONT of the cloth faces -Y, the glTF +Z default front), Z = up. Exported with +Y up.

Materials (by name, the mod finds them by name):
  TeamCloth  - the logo texture goes here. UVs: the cloth front is mapped to the FULL 0..1 square, u to the right and
               v up, not stretched by the swallowtail / pennant cut (the cut simply trims the picture). The back is
               mirrored so the logo reads correctly from both sides. No texture is baked into the .glb.
  Wood, Iron, Leather - fixed, never recolored.

Cloth image sizes the mod should draw: hanging 1:2, standing 1:2, carry 7:11 (see CLOTH_SIZES below), flag 3:2.
"""
import bpy, bmesh, math, os, sys
from mathutils import Vector

args = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
OUT = args[0] if args and args[0] != "preview" else os.path.dirname(os.path.abspath(globals().get("__file__", "x.py")))
PREVIEW = "preview" in args
os.makedirs(OUT, exist_ok=True)

D = bpy.data
for o in list(D.objects):
    D.objects.remove(o)
for m in list(D.meshes):
    D.meshes.remove(m)

WOOD, IRON, LEATHER, CLOTH = 0, 1, 2, 3
CLOTH_SIZES = {"banner_hanging": (1.0, 2.0), "banner_standing": (1.0, 1.9), "banner_carry": (0.7, 1.1), "flag_standard": (1.5, 0.95)}


def material(name, color, rough, metal=0.0):
    m = D.materials.get(name) or D.materials.new(name)
    m.use_nodes = True
    b = m.node_tree.nodes["Principled BSDF"]
    b.inputs["Base Color"].default_value = (*color, 1.0)
    b.inputs["Roughness"].default_value = rough
    b.inputs["Metallic"].default_value = metal
    return m


MATS = [
    material("Wood", (0.30, 0.19, 0.10), 0.85),
    material("Iron", (0.10, 0.10, 0.12), 0.45, 0.8),
    material("Leather", (0.22, 0.12, 0.07), 0.8),
    material("TeamCloth", (0.85, 0.85, 0.85), 1.0),
]


class Part:
    def __init__(self, name):
        self.name = name
        self.bm = bmesh.new()
        self.uv = self.bm.loops.layers.uv.new("UVMap")

    def _finish(self, verts, mat):
        faces = list({f for v in verts for f in v.link_faces})
        bmesh.ops.recalc_face_normals(self.bm, faces=faces)
        for f in faces:
            f.material_index = mat
            n = f.normal
            ax = max(range(3), key=lambda i: abs(n[i]))
            pl = [i for i in range(3) if i != ax]
            for l in f.loops:
                l[self.uv].uv = (l.vert.co[pl[0]] / 0.9, l.vert.co[pl[1]] / 0.4)

    def box(self, lo, hi, mat, bevel=0.0):
        lo, hi = Vector(lo), Vector(hi)
        r = bmesh.ops.create_cube(self.bm, size=1.0)
        for v in r["verts"]:
            v.co = Vector(((lo.x + hi.x) / 2 + v.co.x * (hi.x - lo.x), (lo.y + hi.y) / 2 + v.co.y * (hi.y - lo.y),
                           (lo.z + hi.z) / 2 + v.co.z * (hi.z - lo.z)))
        if bevel:
            edges = list({e for v in r["verts"] for e in v.link_edges})
            bmesh.ops.bevel(self.bm, geom=edges, offset=min(bevel, min(hi - lo) * 0.3), segments=2, profile=0.5,
                            affect="EDGES", clamp_overlap=True)
            verts = list({v for e in edges if e.is_valid for v in e.verts})
        else:
            verts = r["verts"]
        self._finish(verts, mat)

    def cyl(self, p0, p1, r0, mat, r1=None, seg=10):
        a, b = Vector(p0), Vector(p1)
        d = b - a
        r = bmesh.ops.create_cone(self.bm, cap_ends=True, cap_tris=False, segments=seg, radius1=r0,
                                  radius2=r0 if r1 is None else r1, depth=d.length)
        q = Vector((0, 0, 1)).rotation_difference(d.normalized())
        for v in r["verts"]:
            v.co = q @ v.co + (a + b) / 2
        self._finish(r["verts"], mat)

    def ball(self, c, radius, mat):
        r = bmesh.ops.create_uvsphere(self.bm, u_segments=10, v_segments=6, radius=radius)
        for v in r["verts"]:
            v.co += Vector(c)
        self._finish(r["verts"], mat)

    def cloth(self, xmin, width, height, top, y, nx, ny, lift=None, wave=None, thick=0.014):
        """A two-sided, thin cloth hanging from z=top. lift(u): raises the bottom edge (u 0..1) for swallowtails and
        pennants. wave(x, z): y offset. UV = the full rectangle, undistorted by the lift."""
        bm, uvl = self.bm, self.uv
        zfull = top - height
        F, B, UV = {}, {}, {}
        for j in range(ny + 1):
            for i in range(nx + 1):
                u = i / nx
                zb = zfull + (lift(u) if lift else 0.0)
                z = top + (zb - top) * j / ny
                x = xmin + u * width
                off = wave(x, z) if wave else 0.0
                F[i, j] = bm.verts.new((x, y + off - thick / 2, z))
                B[i, j] = bm.verts.new((x, y + off + thick / 2, z))
                UV[i, j] = (u, (z - zfull) / height)
        made = []

        def quad(vs, uvs):
            f = bm.faces.new(vs)
            f.material_index = CLOTH
            for l, t in zip(f.loops, uvs):
                l[uvl].uv = t
            made.append(f)

        for j in range(ny):
            for i in range(nx):
                c = [(i, j), (i, j + 1), (i + 1, j + 1), (i + 1, j)]
                quad([F[k] for k in c], [UV[k] for k in c])
                quad([B[k] for k in reversed(c)], [(1.0 - UV[k][0], UV[k][1]) for k in reversed(c)])
        for j in range(ny):
            for ii, sign in ((0, 1), (nx, -1)):
                c = [(ii, j), (ii, j + 1)]
                vs = [F[c[0]], F[c[1]], B[c[1]], B[c[0]]]
                quad(vs, [UV[c[0]], UV[c[1]], UV[c[1]], UV[c[0]]])
        for i in range(nx):
            for jj in (0, ny):
                c = [(i, jj), (i + 1, jj)]
                vs = [F[c[0]], F[c[1]], B[c[1]], B[c[0]]]
                quad(vs, [UV[c[0]], UV[c[1]], UV[c[1]], UV[c[0]]])
        # one consistent outward winding for the closed slab
        bmesh.ops.recalc_face_normals(bm, faces=made)

    def straps(self, xs, ybar, zbar, rbar, ycloth, ztop):
        """Leather straps that tie the cloth over a crossbar (front plate, over the bar, behind the bar)."""
        for x in xs:
            w = 0.04
            self.box((x - w, ycloth - 0.021, ztop - 0.15), (x + w, ycloth - 0.008, zbar + rbar + 0.01), LEATHER)
            self.box((x - w, ycloth - 0.021, zbar + rbar), (x + w, ybar + rbar + 0.01, zbar + rbar + 0.012), LEATHER)
            self.box((x - w, ybar + rbar, zbar - rbar), (x + w, ybar + rbar + 0.01, zbar + rbar + 0.012), LEATHER)

    def to_object(self):
        me = D.meshes.new(self.name)
        self.bm.to_mesh(me)
        self.bm.free()
        for m in MATS:
            me.materials.append(m)
        for p in me.polygons:
            p.use_smooth = True
        me.set_sharp_from_angle(angle=math.radians(35))
        ob = D.objects.new(self.name, me)
        bpy.context.scene.collection.objects.link(ob)
        return ob


def swallow(depth):
    return lambda u: depth * (1.0 - abs(2.0 * u - 1.0))


def pennant(depth):
    return lambda u: depth * abs(2.0 * u - 1.0)


def hanging():
    p = Part("banner_hanging")
    bar_y, bar_r = -0.10, 0.035
    p.cyl((-0.62, bar_y, 0), (0.62, bar_y, 0), bar_r, WOOD)
    for s in (-1, 1):
        p.ball((s * 0.645, bar_y, 0), 0.058, IRON)
        p.box((s * 0.45 - 0.03, bar_y, -0.03), (s * 0.45 + 0.03, 0.0, 0.03), IRON, 0.008)
        p.box((s * 0.45 - 0.05, 0.0, -0.09), (s * 0.45 + 0.05, 0.02, 0.09), IRON, 0.008)
    yc, top = bar_y - 0.06, 0.012
    p.cloth(-0.5, 1.0, 2.0, top, yc, 16, 32, lift=swallow(0.3),
            wave=lambda x, z: 0.018 * math.sin(3.0 * (top - z)) * min(1.0, (top - z) / 1.0))
    p.straps((-0.36, 0.0, 0.36), bar_y, 0.0, bar_r, yc, top)
    return p.to_object()


def standing():
    p = Part("banner_standing")
    p.box((-0.40, -0.40, 0.0), (0.40, 0.40, 0.12), WOOD, 0.02)
    p.box((-0.24, -0.24, 0.12), (0.24, 0.24, 0.24), WOOD, 0.02)
    p.cyl((0, 0, 0.24), (0, 0, 3.3), 0.05, WOOD)
    p.cyl((0, 0, 0.24), (0, 0, 0.42), 0.075, WOOD)
    p.cyl((0, 0, 3.3), (0, 0, 3.58), 0.055, IRON, r1=0.004)
    p.ball((0, 0, 3.3), 0.06, IRON)
    bar_z = 2.95
    p.cyl((-0.62, 0, bar_z), (0.62, 0, bar_z), 0.035, WOOD)
    for s in (-1, 1):
        p.ball((s * 0.645, 0, bar_z), 0.058, IRON)
    yc, top = -0.095, bar_z + 0.012
    p.cloth(-0.5, 1.0, 1.9, top, yc, 16, 30, lift=swallow(0.3),
            wave=lambda x, z: 0.015 * math.sin(3.2 * (top - z)) * min(1.0, (top - z) / 1.0))
    p.straps((-0.36, 0.0, 0.36), 0.0, bar_z, 0.035, yc, top)
    return p.to_object()


def flag():
    p = Part("flag_standard")
    p.cyl((0, 0, 0), (0, 0, 0.1), 0.30, WOOD, seg=16)
    p.cyl((0, 0, 0.1), (0, 0, 0.2), 0.075, WOOD)
    p.cyl((0, 0, 0.05), (0, 0, 3.4), 0.04, WOOD)
    p.cyl((0, 0, 3.4), (0, 0, 3.72), 0.055, IRON, r1=0.004)
    p.ball((0, 0, 3.4), 0.06, IRON)
    top, height, xmin = 3.3, 0.95, 0.04
    p.cloth(xmin, 1.5, height, top, 0.0, 30, 12, lift=swallow(0.2),
            wave=lambda x, z: 0.075 * ((x - xmin) / 1.5) * math.sin(5.0 * (x - xmin) + 0.6) + 0.01 * math.sin(4.0 * z))
    for z in (top - 0.06, top - height + 0.12):
        p.cyl((0, 0, z), (0, 0, z + 0.09), 0.052, LEATHER)
    return p.to_object()


def carry():
    p = Part("banner_carry")
    p.cyl((0, 0, 0.0), (0, 0, 0.14), 0.004, IRON, r1=0.042)
    p.cyl((0, 0, 0.14), (0, 0, 2.5), 0.035, WOOD)
    p.cyl((0, 0, 0.9), (0, 0, 1.3), 0.043, LEATHER)
    p.cyl((0, 0, 2.5), (0, 0, 2.74), 0.045, IRON, r1=0.004)
    p.ball((0, 0, 2.5), 0.05, IRON)
    bar_z = 2.2
    p.cyl((-0.42, 0, bar_z), (0.42, 0, bar_z), 0.025, WOOD)
    for s in (-1, 1):
        p.ball((s * 0.44, 0, bar_z), 0.04, IRON)
    yc, top = -0.07, bar_z + 0.01
    p.cloth(-0.35, 0.7, 1.1, top, yc, 12, 22, lift=pennant(0.22),
            wave=lambda x, z: 0.012 * math.sin(3.4 * (top - z)) * min(1.0, (top - z) / 0.8))
    p.straps((-0.22, 0.0, 0.22), 0.0, bar_z, 0.025, yc, top)
    return p.to_object()


objs = [hanging(), standing(), flag(), carry()]

# export each model alone, at the origin, with no texture baked in
view = bpy.context.view_layer
for ob in objs:
    for o in objs:
        o.select_set(o is ob)
    view.objects.active = ob
    bpy.ops.export_scene.gltf(filepath=os.path.join(OUT, ob.name + ".glb"), export_format="GLB", use_selection=True,
                              export_apply=True, export_yup=True, export_materials="EXPORT", export_cameras=False,
                              export_lights=False)

# lay them out side by side for the .blend and the preview
for n, ob in enumerate(objs):
    ob.location.x = n * 3.0

if PREVIEW:
    import numpy as np
    w, h = 256, 512
    img = D.images.new("logo_uv_test", w, h)
    a = np.ones((h, w, 4), dtype=np.float32)
    yy, xx = np.mgrid[0:h, 0:w]
    checker = ((xx // 32 + yy // 32) % 2).astype(np.float32)
    a[..., :3] = (0.82 + 0.1 * checker)[..., None] * np.array([0.9, 0.2, 0.2])      # red cloth with a faint check
    cx, cy = w / 2, h * 0.72
    r = np.hypot(xx - cx, yy - cy)
    a[r < 90] = (1, 1, 1, 1)                                                         # white disc where a logo sits
    a[(r < 62)] = (0.1, 0.2, 0.6, 1)
    a[(np.abs(xx - cx) < 14) & (np.abs(yy - cy) < 62)] = (1, 0.8, 0.1, 1)           # an upright bar: shows orientation
    a[(yy > h - 14)] = (0, 0, 0, 1)                                                  # black strip along the TOP edge
    a[:, :10] = (0, 0.5, 0, 1)                                                       # green on the left (u = 0)
    img.pixels = a.ravel()
    cm = MATS[CLOTH]
    tex = cm.node_tree.nodes.new("ShaderNodeTexImage")
    tex.image = img
    cm.node_tree.links.new(tex.outputs["Color"], cm.node_tree.nodes["Principled BSDF"].inputs["Base Color"])

bpy.ops.wm.save_as_mainfile(filepath=os.path.join(OUT, "team_banners.blend"))
print("banners written to", OUT)
